INSERT INTO purpose VALUES('surface-lsp-core','complete::completions','function','The completions at `position` of `text`, the document at `uri` whose copy keeps `hovering`, under `grammar` whose forms are `forms`, each type spelled in `printer`''s style and label details given when `labels` says the client shows them.',NULL,'fits','sound',NULL);
