INSERT INTO purpose VALUES('surface-lsp-core','hover::hovering_laid','function','What the hovers of `text`, the document at `path` that `session` judges, laid out as `laid`, read: one typed run per text, rather than one per hover, and no parse when the judgement of `text` kept its table and the heads read off its parse (`judged`).',NULL,'fits','sound',NULL);
